import java.util.Scanner;

public class Main {
    static final int MAX_SIZE = 1000010;
    static final long MODULUS = 1000000007;
    static boolean[] visitedFlags = new boolean[MAX_SIZE];

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int pValue = scanner.nextInt();
        int kValue = scanner.nextInt();
        long answer = 1;

        if (kValue != 0) {
            int invK = 0;
            if (kValue == 1) {
                answer = pValue;
            } else {
                // Find modular inverse of kValue modulo pValue
                for (int i = 1; i < pValue; i++) {
                    if ((long) i * kValue % pValue == 1) {
                        invK = i;
                        break;
                    }
                }
                for (int i = 1; i < pValue; i++) {
                    if (!visitedFlags[i]) {
                        visitedFlags[i] = true;
                        int count = 1;
                        int j = (int) ((long) kValue * i % pValue);
                        int m = invK;
                        while (!visitedFlags[j]) {
                            visitedFlags[j] = true;
                            count++;
                            m = (int) ((long) m * invK % pValue);
                            j = (int) ((long) kValue * j % pValue);
                        }
                        if (m == 1) {
                            answer = (answer * pValue) % MODULUS;
                        }
                    }
                }
            }
        } else {
            for (int i = 1; i < pValue; i++) {
                answer = (answer * pValue) % MODULUS;
            }
        }
        System.out.println(answer);
        scanner.close();
    }
}
